import{z as o,x as A,o as B,c as d,q as i,j as s,D as r,d as e,s as n,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"页与槽","description":"","frontmatter":{"title":"页与槽","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/page-slot.md","filePath":"cs/page-slot.md","lastUpdated":1791063341000}'),p={name:"cs/page-slot.md"};function D(m,a,h,c,f,u){const t=A("Mermaid");return B(),d("div",null,[a[2]||(a[2]=i('<h1 id="页与槽" tabindex="-1">页与槽 <a class="header-anchor" href="#页与槽" aria-label="Permalink to &quot;页与槽&quot;">​</a></h1><div class="epigraph"><p>磁盘按页搬；页内用槽目录指向变长记录，元组身份才能与物理偏移分开。</p><footer>—— 据 Gray and Reuter, Transaction Processing；Ramakrishnan and Gehrke 对页组织的整理</footer></div><p><a href="/cs/covering-index">上一课</a>把外模式收到视图。本课不重讲物化维护。缺口是：关系最终要落在<a href="/cs/file-bytestream">文件字节流</a>上，而缓冲池按页换入换出。没有页内布局，就没有稳定的记录地址，索引只能指向「现在碰巧的偏移」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>操作系统的文件是字节序列；数据库需要定长页（常 4KiB 或 8KiB），与<a href="/cs/buffer-dirty">缓冲与脏页</a>对齐。页里若把记录紧密拼接，变长更新会移动后续字节，所有指针作废。缺口不是「再讲一遍文件」，而是<strong>页头 + 槽目录 + 记录空间</strong>：槽存偏移，记录可在页内滑动，对外只暴露页号与槽号。</p><p><span class="marginnote">可以把它想象成酒店前台：客人（记录）在楼里换了房间没关系，前台钥匙柜（槽目录）里的小纸条改一下就行，客人对外登记的房号（槽号）始终不变。索引就是只记了「房号」的访客——它不需要知道客人实际睡在哪张床。</span></p><p>本课不引入 B+ 树内部节点格式，那是索引课。这里只钉堆文件与索引页共用的槽化页。</p><p><span class="marginnote">记录标识 rid = (页号, 槽号)。槽号稳定，记录在页内搬家只改槽里的偏移。这是后课索引与堆文件的共同地址。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>页头记下空闲空间、槽个数、校验或 LSN（后课 WAL 才用）。槽目录从页尾向页头长，记录从页头向页尾长，中间是自由空间。删除把槽标空，或置删除位；空间可经整理收回。变长字段用偏移数组；超长字段溢出到溢出页，本课只承认有溢出，不把 TOAST 写完。</p><p><span class="marginnote">两端相向生长是省空间的关键：以 8 KiB 页为例，记录从页头往下占、槽目录从页尾往上占，中间剩下的就全是可用自由空间，不需要额外整理就不会出现「明明有空间却拼不出一段连续字节」的浪费。</span></p>',11)),(B(),s(l,null,{default:r(()=>[n(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20FILE%5B%22%E6%96%87%E4%BB%B6%E5%AD%97%E8%8A%82%E6%B5%81%22%5D%20--%3E%20PAGE%5B%22%E5%AE%9A%E9%95%BF%E9%A1%B5%22%5D%0A%20%20PAGE%20--%3E%20SLOT%5B%22%E6%A7%BD%E7%9B%AE%E5%BD%95%22%5D%0A%20%20SLOT%20--%3E%20RID%5B%22rid%3A%20%E9%A1%B5%E5%8F%B7%2B%E6%A7%BD%E5%8F%B7%22%5D%0A%20%20RID%20--%3E%20HEAP%5B%22%E5%90%8E%E8%AF%BE%3A%20%E5%A0%86%E6%96%87%E4%BB%B6%E4%B8%8E%E8%81%9A%E7%B0%87%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("槽化使更新局部：加长记录若本页放不下，才迁移到新页并在原槽留转发，索引不必立刻全改（转发有代价）。定长记录可以取消槽，用算术算偏移；变长与空值一多，槽更合算。校验和与页 LSN 把「这一页的版本」钉死，崩溃后"),E("a",{href:"/cs/aries-recovery"},"ARIES"),e("才知道页旧不旧。")],-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"常见误区：初学者容易以为记录一搬家，所有指向它的索引项都得马上重写。实际上原槽里留着一条「转发地址」，索引顺着旧 rid 也能找到新位置，回头再批量改——代价只是每次查找多绕一跳，用小额开销换来更新即刻完成。")],-1)),a[6]||(a[6]=E("p",null,"第一张图回答「rid 从文件到索引怎么一路成型」；一次插入、更新、删除分别落在页内的哪个部件上，是另一个问题。",-1)),(B(),s(l,null,{default:r(()=>[n(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20INS%5B%22%E6%8F%92%E5%85%A5%E8%AE%B0%E5%BD%95%22%5D%20--%3E%20GROW%5B%22%E9%A1%B5%E5%A4%B4%E4%BE%A7%E5%86%99%E5%85%A5%E5%86%85%E5%AE%B9%20%E9%A1%B5%E5%B0%BE%E4%BE%A7%E6%A7%BD%E7%9B%AE%E5%BD%95%E9%95%BF%E4%B8%80%E6%A0%BC%22%5D%0A%20%20UPD%5B%22%E6%9B%B4%E6%96%B0%E5%90%8E%E8%AE%B0%E5%BD%95%E5%8F%98%E9%95%BF%22%5D%20--%3E%20FIT%7B%22%E6%9C%AC%E9%A1%B5%E8%BF%98%E6%94%BE%E5%BE%97%E4%B8%8B%3F%22%7D%0A%20%20FIT%20--%3E%7C%22%E6%94%BE%E5%BE%97%E4%B8%8B%22%7C%20MOVE%5B%22%E9%A1%B5%E5%86%85%E6%BB%91%E5%8A%A8%20%E5%8F%AA%E6%94%B9%E6%A7%BD%E4%B8%AD%E5%81%8F%E7%A7%BB%22%5D%0A%20%20FIT%20--%3E%7C%22%E6%94%BE%E4%B8%8D%E4%B8%8B%22%7C%20OUT%5B%22%E8%BF%81%E5%8E%BB%E6%96%B0%E9%A1%B5%20%E5%8E%9F%E6%A7%BD%E7%95%99%E8%BD%AC%E5%8F%91%22%5D%0A%20%20DEL%5B%22%E5%88%A0%E9%99%A4%E8%AE%B0%E5%BD%95%22%5D%20--%3E%20TOMB%5B%22%E6%A7%BD%E6%A0%87%E7%A9%BA%E6%88%96%E7%BD%AE%E5%88%A0%E9%99%A4%E4%BD%8D%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<p>本课不处理列存页、压缩页的全部变体；列存把属性切开，槽的含义变成列块，主干仍以行页为默认图像。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲磁盘调度、RAID。页大小是工程常数，与文件系统块可以不同，库自己做缓冲。也不把「一行一页」当默认——那是极端宽行或溢出。</p><p>行锁若以 rid 为粒度，槽重用必须与事务可见性对齐，否则会锁错对象——那是后课并发的交界，本课只把 rid 交出去。后课默认：元组有 rid；堆与索引都通过页与槽找记录，而不是通过文件的字节下标。</p><p>页是缓冲池与日志共同的粒度。后课 WAL 的 pageLSN 打在页头上，槽目录是页内的寻址，两者一起才构成可恢复的记录。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>视图已在逻辑层；本课把记录放进槽化页，交出 rid。</li><li>槽把身份与页内偏移分开，供索引与堆共用。</li><li>记录如何排成堆、何时按键聚簇，是后课缺口。</li><li>出处：Gray and Reuter；Ramakrishnan and Gehrke；Garcia-Molina, Ullman and Widom。</li></ul>',7))])}const g=o(p,[["render",D]]);export{_ as __pageData,g as default};
